// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "name", "sym"); }

    function testFuzz_property(uint256 burnAmount, address caller) public {
        vm.assume(caller != address(0) && caller != c.owner());
        burnAmount = bound(burnAmount, 0, c.balanceOf(c.owner()));

        vm.prank(c.owner());
        c.transfer(caller, burnAmount);

        uint256 balanceBefore = c.balanceOf(caller);
        bool ok;
        vm.prank(caller);
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = c.balanceOf(caller);

        assertTrue(!ok && balanceBefore == balanceAfter);
    }
}
